import { Hono } from 'hono';
import encodedAssets from 'virtual:client-assets';
import { accessAuth } from './access';
import api from './index';
import { decodeAssets, serveStatic } from './static';

/**
 * Production entry point (wrangler.deploy.json, generated by scripts/prepare-deploy.mjs).
 * /api/* goes to the API; everything else is the web app, served from the Worker bundle.
 * Both require an identity verified by Cloudflare Access, so without Access nothing is served.
 */

const assets = decodeAssets(encodedAssets);

const site = new Hono<{ Bindings: Env; Variables: { user: string } }>();
site.use('*', accessAuth());
site.all('*', (c) => serveStatic(c.req.raw, assets));

export default {
  fetch(request, env, ctx) {
    const { pathname } = new URL(request.url);
    if (pathname === '/api' || pathname.startsWith('/api/')) return api.fetch(request, env, ctx);
    return site.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<Env>;
